import{_ as r,o,c as n,ag as t}from"./chunks/framework.yGqRar0R.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),a={name:"guide/introduction.md"};function s(i,e,l,d,c,g){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="" tabindex="-1"><img src="https://cdn.modrinth.com/data/cached_images/7115a8404f7d6a94fd7aab586d6c4de1e9b3846c.png" alt="SLS Standalone Logo"> <a class="header-anchor" href="#" aria-label="Permalink to &quot;![SLS Standalone Logo](https://cdn.modrinth.com/data/cached_images/7115a8404f7d6a94fd7aab586d6c4de1e9b3846c.png)&quot;">​</a></h1><p><strong>SLS</strong> is a system for managing networks of <strong>ephemeral game servers</strong>, designed for games like <strong>Minecraft, Hytale, Garry’s Mod, and Rust</strong>. It lets you <strong>spin up and tear down servers quickly</strong>, with each server <strong>fully isolated and reproducible</strong>.</p><hr><p>Servers are defined using <a href="./blueprints/introduction.html"><strong>Blueprints</strong></a>, where you can specify everything from:</p><ul><li>Server version and resource limits</li><li>Volumes mounts</li><li>Config patches</li><li>Custom configuration</li></ul><p>From a single <a href="./blueprints/introduction.html">Blueprint</a>, you can create <strong>as many server instances as needed</strong>.</p><h2 id="key-components" tabindex="-1">Key Components <a class="header-anchor" href="#key-components" aria-label="Permalink to &quot;Key Components&quot;">​</a></h2><ul><li><a href="./installing-protocube.html"><strong>Protocube</strong></a> – The <strong>core controller</strong> of SLS. Tracks all servers, provides an API for management, and routes requests to backend nodes.</li><li><a href="./installing-daemon.html"><strong>Daemon</strong></a> (nodes) – The <strong>server control plane</strong>. Runs on each physical machine, connects to Protocube, and manages servers inside Docker containers.</li><li><a href="/sls-docs/reference/api/"><strong>S4J</strong></a> – A <strong>Java API wrapper</strong> for the SLS API.</li></ul><hr><blockquote><p>SLS is ideal for networks that need <strong>fast, consistent, and isolated server environments</strong>. Whether you’re running <strong>minigames</strong>, <strong>private worlds</strong>, or <strong>large server networks</strong>, SLS gives you <strong>full control</strong> over how servers are <strong>created, configured, and managed</strong>.</p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><p><strong>Isolated &amp; Reproducible Environments</strong> Every server runs in its own Docker container and is created exactly as defined in its <a href="./blueprints/introduction.html">Blueprint</a> ensuring consistency across every instance.</p></li><li><p><strong>Zero-Copy Instancing (COW)</strong> Avoid repeated file copying and reinstallations. SLS uses copy-on-write mounts to efficiently create new servers with minimal overhead.</p></li><li><p><strong>Horizontal Scaling</strong> Easily scale your network by adding more nodes. SLS automatically utilizes available resources across your infrastructure.</p></li><li><p><strong>Real-Time Status &amp; Events</strong> Track server lifecycle states (starting, online, stopping) and subscribe to an event stream for real-time updates.</p></li><li><p><strong>Built-in Load Distribution</strong> Servers are automatically distributed across nodes to balance load and optimize resource usage.</p></li><li><p><strong>Custom Software Support</strong> Define and run your own server types using flexible <a href="./software-configurations/introduction.html">software configurations</a>.</p></li><li><p><strong>HTTP API Control</strong> Fully manage servers programmatically through a simple and powerful HTTP API.</p></li></ul><h2 id="demo" tabindex="-1">Demo <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;Demo&quot;">​</a></h2><p>A live demo <strong>Minecraft</strong> network is available if you want to try SLS in action.</p><ul><li><strong>Server address:</strong> <code>demo.protoxon.com</code></li></ul><p>This demo showcases how servers can be dynamically created and managed in a real environment.</p><p>The demo utilizes the <a href="./vsls/"><strong>vSLS</strong></a> plugin.</p><h2 id="more-information" tabindex="-1">More Information <a class="header-anchor" href="#more-information" aria-label="Permalink to &quot;More Information&quot;">​</a></h2><p>For full documentation, examples, and source code, view the <strong><a href="https://github.com/jessefaler/SLS" target="_blank" rel="noreferrer">SLS GitHub repository</a></strong>.</p>',19)])])}const p=r(a,[["render",s]]);export{m as __pageData,p as default};
